typedef unsigned long long big_int;

class stringx;

class string_buf
{
	friend class stringx;
	friend stringx operator+(const stringx &, const stringx &);
	big_int *data;
	int ref_count;
	int char_length;
	int block_length;
	int max_blocks;
};

class stringx
{
	char *chars;
	string_buf *my_buf;

public:
	stringx();
	stringx(const stringx &cp);
	stringx(const char *str, int len = -1);
	explicit stringx(int i);
	~stringx();
	void append(const stringx &cp);
	void make_room(int size);
	stringx &operator+=(const stringx &cp);

	friend stringx operator+(const stringx &, const stringx &);
};

inline stringx operator+( const stringx& lhs, const stringx& rhs )
{
  stringx foo;

  foo.make_room(lhs.my_buf->char_length + rhs.my_buf->char_length);
  foo.append(lhs);
  foo.append(rhs);

  return foo;
}

class TextString
{
public:
	virtual ~TextString();
	virtual void Update(float);
	virtual void Draw();
	virtual void setHJustify(int);
	virtual void setVJustify(int);
	virtual void setFont(void *);
	virtual void setButtonScale(float);
	virtual void numberSpacing(bool);
	virtual void changeText(stringx t);
};

extern stringx ksGlobalTextArray[];
enum { GT_PHOTOSHOOT_POINTS = 68 };

class PhotoWidget
{
	char padding[244];
	TextString *pointText;
	int score;
	int *scorePtr;

private:
	virtual void SetPointText(void);
};

void PhotoWidget::SetPointText(void)
{
	stringx	text;

	if (scorePtr)
	{
		text += stringx(score);
		text += stringx(" ")+ksGlobalTextArray[GT_PHOTOSHOOT_POINTS];
		pointText->changeText(text);
	}
	else
		pointText->changeText("");
}
